    /// <summary>Every content type known to Magika, in upstream declaration order.</summary>
    public static IReadOnlyList<ContentTypeInfo> All => Items;

    /// <summary>Looks up a content type by its Magika label.</summary>
    public static ContentTypeInfo Get(string label)
    {
        ArgumentNullException.ThrowIfNull(label);
        if (!ByLabel.TryGetValue(label, out ContentTypeInfo? info))
        {
            throw new ArgumentException($"Unknown Magika content type '{label}'.", nameof(label));
        }

        return info;
    }

    /// <summary>Returns the content type, or <see langword="null"/> when the label is unknown.</summary>
    public static ContentTypeInfo? TryGet(string label)
    {
        ArgumentNullException.ThrowIfNull(label);
        return ByLabel.TryGetValue(label, out ContentTypeInfo? info) ? info : null;
    }
